mapper.select:
SELECT id, annual, customer_name, user_name, created_at, review_status, review_reject_reason, attachment_id from t_annual_agreement
is_deleted = #{param.is_deleted}
AND annual = #{param.annual}
AND customer_name LIKE CONCAT('%', #{param.customerName}, '%')
AND user_name LIKE CONCAT('%', #{param.userName}, '%')
AND created_at LIKE CONCAT('%', #{param.createdAt}, '%')
AND review_status LIKE CONCAT('%', #{param.reviewStatus}, '%')
AND review_reject_reason LIKE CONCAT('%', #{param.reviewRejectReason}, '%')
AND attachment_id = #{param.attachment_id}
